'use strict';
const $=s=>document.querySelector(s),arr=x=>Array.isArray(x)?x:[],finite=x=>typeof x==='number'&&Number.isFinite(x);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(x,n=0)=>finite(x)?x.toLocaleString('en-GB',{maximumFractionDigits:n}):'Unknown';
const human=x=>String(x??'').replaceAll('_',' '),uniq=xs=>[...new Set(xs.filter(x=>x!==null&&x!==undefined&&x!==''))];
const txt=x=>finite(x)?num(x,4):Array.isArray(x)?x.map(txt).join(' · '):x&&typeof x==='object'?Object.entries(x).map(([k,v])=>`${human(k)}: ${txt(v)}`).join('; '):x==null?'':String(x);
const TYPES={observed_question_answer:{label:'Printed Q/A locator',short:'Documentary',className:'documentary'},unverified_question_candidate:{label:'Unverified question cue',short:'Candidates',className:'candidate'},generated_reading_prompt:{label:'Generated reading prompt',short:'Reading prompts',className:'prompt'},curated_comparison:{label:'Curated analyst reading',short:'Curated readings',className:'curated'}};
const S={modules:{},manifest:null,errors:{},profiles:new Map(),records:[],recordMap:new Map(),search:null,shards:new Map(),pending:new Map(),token:0,page:1,selected:null,query:'',prefix:false,filter:{type:'all',channel:'all',origin:'all',status:'all',topic:'all',from:'',to:''},graphChannels:[],relations:[],node:null,hops:1,graphPage:1,trigger:null};
const P=()=>arr(S.modules.profiles?.profiles),B=()=>S.modules.bank||{},C=()=>S.modules.curated||{},G=()=>S.modules.graph||{};
const profile=id=>S.profiles.get(id),sourceTitle=id=>profile(id)?.title||id||'Unreported source';
const channelId=p=>p?.channel_id,channelName=id=>P().find(p=>channelId(p)===id)?.channel_name||id||'Unreported context';
const contexts=()=>uniq(P().map(channelId)).map(id=>({id,name:channelName(id)})).sort((a,b)=>a.name.localeCompare(b.name));
const sourceIds=r=>uniq([...arr(r?.source_ids),r?.source_id]),origin=p=>p?.text_origin||'unknown',date=p=>p?.publication_date||p?.published_at||null;
const sourceWords=p=>p?.words??p?.total_words??p?.coverage?.total_words??null;
const topTerms=p=>arr(p?.top_terms).map(x=>typeof x==='string'?x:Array.isArray(x)?x[0]:x.term);
const typeInfo=type=>TYPES[type]||{label:human(type),short:human(type),className:'candidate'};
const badge=type=>`<span class="record-type ${typeInfo(type).className}">${esc(typeInfo(type).label)}</span>`;
const status=s=>`<span class="status">${esc(human(s||'unknown'))}</span>`;
const safeFile=f=>typeof f==='string'&&/^(?:[A-Za-z0-9_-]+\/)*[A-Za-z0-9_.-]+$/.test(f)&&!f.split('/').includes('..')?f:null;
const external=(url,label='Original publisher')=>{try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?`<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label);}catch{return `<span class="muted">${esc(label)} unavailable</span>`;}};
const facts=rows=>`<dl class="facts">${rows.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${v===null||v===undefined||v===''?'Unknown':v}</dd>`).join('')}</dl>`;
const empty=s=>`<div class="empty">${esc(s)}</div>`,error=s=>`<div class="error">${esc(s)}</div>`;
const unavailable=k=>empty(`${human(k)} is ${S.errors[k]?'unavailable in this load':'not supplied in this release'}. No substitute evidence is shown.`);
const table=(label,heads,rows)=>`<div class="table-wrap" tabindex="0" role="region" aria-label="${esc(label)}"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`;
const section=(title,description,body)=>`<section class="section"><div class="section-head"><h2>${esc(title)}</h2><p>${esc(description)}</p></div>${body}</section>`;
const heading=(eyebrow,title,description)=>`<div class="page-head"><div><span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(title)}</h1><p class="intro">${esc(description)}</p></div></div>`;
const options=(xs,selected,format=x=>human(x))=>xs.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(format(x))}</option>`).join('');
const allOptions=(xs,selected,label='All')=>`<option value="all">${esc(label)}</option>${options(uniq(xs).sort(),selected)}`;
const announce=s=>{$('#announcer').textContent=s;};
function url(view='bank',params={}){const u=new URL(location.href);u.search='';u.searchParams.set('view',view);Object.entries(params).forEach(([k,v])=>{if(v!==null&&v!==undefined&&v!==''&&v!=='all')u.searchParams.set(k,Array.isArray(v)?v.join(','):String(v));});return u.pathname+u.search;}
function bankParams(){return {...S.filter,q:S.query,prefix:S.prefix?'1':'',record:S.selected};}
const recordLink=(id,label)=>`<a data-record="${esc(id)}" href="${esc(url('bank',{...bankParams(),record:id}))}">${esc(label||S.recordMap.get(id)?.display_question||id)}</a>`;
const sourceLink=(id,label)=>`<a data-source="${esc(id)}" href="${esc(url('source',{source:id}))}">${esc(label||sourceTitle(id))}</a>`;
const contextLink=(id,label)=>`<a data-context="${esc(id)}" href="${esc(url('context',{context:id}))}">${esc(label||channelName(id))}</a>`;
const graphLink=(id,label='Follow connections')=>`<a data-graph-node="${esc(id)}" href="${esc(url('graph',{node:id}))}">${esc(label)}</a>`;
const inspectButton=(kind,id,label='Inspect provenance')=>`<button class="text" type="button" data-inspect="${esc(kind)}" data-id="${esc(id)}">${esc(label)}</button>`;
async function fetchBytes(file,descriptor={}){if(!safeFile(file))throw new Error('Invalid release path.');const r=await fetch(file,{cache:'no-cache'});if(!r.ok)throw new Error(`${file}: HTTP ${r.status}`);const b=await r.arrayBuffer();if(descriptor.bytes!==undefined&&b.byteLength!==descriptor.bytes)throw new Error(`${file}: release size mismatch`);if(descriptor.sha256&&crypto.subtle){const h=[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');if(h!==descriptor.sha256)throw new Error(`${file}: release hash mismatch`);}return b;}
async function fetchJSON(file,d){const x=JSON.parse(new TextDecoder().decode(await fetchBytes(file,d)));if(x.synthetic===true||x.synthetic_fixture_run===true)throw new Error('Synthetic observations cannot replace source-bound records.');return x;}
function curatedRecords(){return arr(C().questions).map(q=>{const cards=arr(C().cards).filter(c=>c.question_id===q.question_id),ids=uniq(cards.map(c=>c.source_id));return {record_id:'curated:'+q.question_id,type:'curated_comparison',question_id:q.question_id,question_origin:q.question_type,display_question:q.question,source_ids:ids,answer_status:cards.length?'qualified_analyst_paraphrase':'no_curated_answer',answer_paraphrase:cards.map(c=>c.paraphrase).join(' '),reading_status:cards.some(c=>c.annotation?.type==='new_manual_ai_bounded_reading')?'bounded_model_agent_reading':'verified_prior_annotation_reuse',topic_terms:uniq([q.topic_id]),cards,question:q};});}
function buildIndex(){S.profiles=new Map(P().map(p=>[p.source_id,p]));S.records=[...curatedRecords(),...arr(B().records)];S.recordMap=new Map();S.recordsBySource=new Map();S.graphNodes=new Map(arr(G().nodes).map(n=>[n.id,n]));for(const r of S.records){if(!r.record_id||S.recordMap.has(r.record_id))throw new Error('Duplicate or missing catalog record ID.');S.recordMap.set(r.record_id,r);for(const id of sourceIds(r)){if(!S.recordsBySource.has(id))S.recordsBySource.set(id,[]);S.recordsBySource.get(id).push(r);}}if(typeof MiniSearch==='undefined')throw new Error('The pinned local MiniSearch library did not load.');S.search=new MiniSearch({idField:'id',fields:['question','summary','metadata'],storeFields:[],tokenize:text=>String(text).normalize('NFKC').match(/[\p{L}\p{M}\p{N}]+(?:['’][\p{L}\p{M}\p{N}]+)*/gu)||[],processTerm:t=>t.toLowerCase(),searchOptions:{combineWith:'OR',prefix:false,fuzzy:false}});S.search.addAll(S.records.map(r=>{const ps=sourceIds(r).map(profile).filter(Boolean);return {id:r.record_id,question:r.display_question||'',summary:r.type==='curated_comparison'?r.answer_paraphrase||'':'',metadata:[txt(r.topic_terms),...ps.flatMap(p=>[p.title,p.channel_name,p.creator_name,p.publisher_name,...topTerms(p)])].filter(Boolean).join(' ')};}));}
async function load(){try{$('#main').setAttribute('aria-busy','true');S.manifest=await fetchJSON('manifest.json');if(S.manifest.schema_version!==1||!S.manifest.modules?.profiles||!S.manifest.modules?.bank)throw new Error('Unsupported knowledge release manifest.');const entries=Object.entries(S.manifest.modules),results=await Promise.allSettled(entries.map(async([k,d])=>[k,await fetchJSON(d.file,d)]));S.modules={};S.errors={};results.forEach((r,i)=>r.status==='fulfilled'?S.modules[r.value[0]]=r.value[1]:S.errors[entries[i][0]]=r.reason.message);const failed=entries.filter(([k,d])=>(d.required||['profiles','bank','curated','graph'].includes(k))&&S.errors[k]);if(failed.length)throw new Error(failed.map(([k])=>S.errors[k]).join(' · '));buildIndex();readRoute();render();announce('The bound knowledge catalog is ready.');}catch(e){$('#main').innerHTML=heading('RELEASE UNAVAILABLE','The knowledge bank could not load.','No placeholder question or answer is substituted.')+error(e.message)+'<button id="retry" type="button">Retry release</button>';$('#retry').onclick=load;}finally{$('#main').setAttribute('aria-busy','false');}}
function readRoute(){const q=new URLSearchParams(location.search);S.route=q.has('source')?{view:'source',id:q.get('source')}:q.has('context')?{view:'context',id:q.get('context')}:{view:q.get('view')||'bank'};S.selected=q.get('record');S.query=q.get('q')||'';S.prefix=q.get('prefix')==='1';for(const k of Object.keys(S.filter))S.filter[k]=q.get(k)||(['from','to'].includes(k)?'':'all');S.graphChannels=q.has('channels')?q.get('channels').split(',').filter(Boolean):[];S.node=q.get('node');S.graphLabel=q.get('label')||'all';S.hops=q.get('hops')==='2'?2:1;S.relations=q.has('relations')?q.get('relations').split(',').filter(Boolean):relationKeys().filter(k=>k!=='derived_semantic_neighbor');}
function go(view,params={}){if($('#inspector').open)$('#inspector').close();history.pushState(null,'',url(view,params));S.page=1;S.graphPage=1;readRoute();render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);}
function render(){const token=++S.token;document.querySelectorAll('[data-view]').forEach(a=>a.dataset.view===S.route.view?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));const views={bank:bankView,sources:sourcesView,source:()=>sourceView(S.route.id),context:()=>contextView(S.route.id),graph:graphView,methods:methodsView};$('#main').innerHTML=(views[S.route.view]||bankView)();bind();if(S.route.view==='bank'&&S.selected)hydrateRecord(S.selected,token);document.title=(S.route.view==='source'?sourceTitle(S.route.id):S.route.view==='context'?channelName(S.route.id):'Transcript knowledge')+' · Channeling Atlas';}
function dominant(p){const rows=arr(p?.topic_profile);return rows.length?[...rows].sort((a,b)=>b.weight-a.weight||a.topic_id.localeCompare(b.topic_id))[0].topic_id:null;}
function sourceMatchesFilters(p){return !!p&&(S.filter.channel==='all'||p.channel_id===S.filter.channel)&&(S.filter.origin==='all'||origin(p)===S.filter.origin)&&(S.filter.topic==='all'||dominant(p)===S.filter.topic)&&(!S.filter.from||date(p)&&date(p).slice(0,10)>=S.filter.from)&&(!S.filter.to||date(p)&&date(p).slice(0,10)<=S.filter.to);}
function filtered(){let rows=S.records;if(S.query.trim()){const results=S.search.search(S.query,{combineWith:'OR',prefix:S.prefix,fuzzy:false});rows=results.map(x=>({...S.recordMap.get(x.id),search_score:x.score}));}return rows.filter(r=>{const ps=sourceIds(r).map(profile).filter(Boolean),sourceMatch=ps.some(sourceMatchesFilters);return (S.filter.type==='all'||r.type===S.filter.type)&&(S.filter.status==='all'||(r.reading_status||'unknown')===S.filter.status)&&sourceMatch;});}
function bankView(){return heading('QUESTION & ANNOTATION INDEX','Find a question. Follow its evidence.','Search public cue labels, reading prompts, analyst paraphrases and source metadata. Exact transcript bodies remain outside this browser index.')+`<form id="search-form" class="searchbar"><label>Search the public knowledge index<input type="search" id="query" value="${esc(S.query)}" placeholder="A concept, question cue or publishing context"></label><button type="submit">Search records</button><label class="check"><input type="checkbox" id="prefix" ${S.prefix?'checked':''}>Match word prefixes too (off by default)</label></form><div class="actions"><a data-type="curated_comparison" href="${esc(url('bank',{type:'curated_comparison'}))}">Open source-bound curated readings (${S.modules.curated?num(arr(C().questions).length):'pending'})</a></div><div class="type-strip">${Object.entries(TYPES).map(([k,v])=>`<a data-type="${k}" aria-current="${S.filter.type===k}" href="${esc(url('bank',{...bankParams(),type:k,record:null}))}">${esc(v.short)} <strong>${k==='curated_comparison'&&!S.modules.curated?'Unknown':num(S.records.filter(r=>r.type===k).length)}</strong></a>`).join('')}</div><details><summary>What these four record types mean</summary><p class="caption">Printed Q/A locators preserve documentary structure; their public cue labels are not the original wording. Unverified question cues can come from written text, captions or ASR; they can be rhetorical, mispunctuated or recognition errors. Actual text origin is shown with the source. Generated prompts are research aids. Curated readings contain qualified analyst paraphrases tied to inspected spans. None of these labels implies verified speakers or a complete human reading. Structured documentary Q/A extraction is supported for the Ra printed roles; zero observed pairs elsewhere means no recognized documentary boundary, not no audience or interview questions.</p></details><div class="workbench">${filterPanel()}<div class="results-workspace"><div id="results-meta">${resultMeta()}</div><div class="reading-workspace"><div><div id="results" class="result-list">${resultRows()}</div><div id="pagination">${pagination()}</div></div><aside id="reader" class="reader" aria-label="Selected knowledge record">${S.selected?'<p class="loading">Loading the bound record…</p>':empty('Choose a record to inspect its answer status, source edition and evidence locators.')}</aside></div></div></div>`;}
function filterPanel(){const topics=uniq(P().flatMap(p=>arr(p.topic_profile).map(t=>t.topic_id)));return `<details class="filters" open><summary>Refine the record set</summary><div class="filter-fields"><label>Record type<select id="filter-type"><option value="all">All four types</option>${options(Object.keys(TYPES),S.filter.type,k=>TYPES[k].label)}</select></label><label>Publishing context<select id="filter-channel"><option value="all">All publishing contexts</option>${options(contexts().map(c=>c.id),S.filter.channel,channelName)}</select></label><label>Source text origin<select id="filter-origin">${allOptions(P().map(origin),S.filter.origin,'All origins')}</select></label><label>Reading status<select id="filter-status">${allOptions(S.records.map(r=>r.reading_status||'unknown'),S.filter.status,'All reading statuses')}</select></label><label>Source’s largest lexical factor<select id="filter-topic">${allOptions(topics,S.filter.topic,'All source factors')}</select></label><label>Published from<input id="filter-from" type="date" value="${esc(S.filter.from)}"></label><label>Published through<input id="filter-to" type="date" value="${esc(S.filter.to)}"></label><p class="caption">Dates refer to publication metadata. Date ranges exclude unknown dates. Source factors are not question-topic or entity labels.</p><button type="button" id="clear-filters" class="secondary">Clear all filters</button><button type="button" id="export-records" class="secondary">Export filtered CSV</button><button type="button" id="export-records-json" class="secondary">Export filtered JSON</button></div></details>`;}
function resultMeta(){const rows=filtered();return `<div class="result-meta"><strong id="record-count">${num(rows.length)} matching records</strong><span>${num(S.records.length)} catalog items · ${num(arr(B().records).length)} extraction/prompt entries + ${num(arr(C().questions).length)} curated questions</span></div><p class="caption">${S.query?`MiniSearch BM25+ · OR token matching${S.prefix?' · prefix matching enabled':''}. Ranking is not evidence strength.`:'Original catalog order; no relevance ranking without a query.'} Multi-source curated questions count once globally. At least one linked source must satisfy every source filter; the full comparison retains its other source editions.</p>${S.selected&&!rows.some(r=>r.record_id===S.selected)?'<p class="caption">The selected record is outside these filters; its evidence stays open for reference.</p>':''}`;}
function resultRows(){const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/20));S.page=Math.min(Math.max(1,S.page),pages);return rows.slice((S.page-1)*20,S.page*20).map(r=>{const ids=sourceIds(r),ps=ids.map(profile).filter(Boolean);return `<article class="result-item ${r.record_id===S.selected?'selected':''}">${badge(r.type)}<h3>${recordLink(r.record_id,r.display_question||'Unlabeled record')}</h3><p class="meta">${esc(uniq(ps.map(p=>p.channel_name)).join(' · '))}<br>${esc(ids.length===1?sourceTitle(ids[0]):`${ids.length} linked source editions`)}</p><p class="meta">${esc(human(r.answer_status||'answer status unknown'))} · ${esc(human(r.reading_status||'reading status unknown'))}</p></article>`;}).join('')||empty('No records match these public index fields and filters. Clear filters or search a different term.');}
function pagination(){const pages=Math.max(1,Math.ceil(filtered().length/20));return `<div class="pagination"><button type="button" class="secondary" data-page="${S.page-1}" ${S.page===1?'disabled':''}>Previous</button><span>Page ${S.page} of ${pages}</span><button type="button" class="secondary" data-page="${S.page+1}" ${S.page===pages?'disabled':''}>Next</button></div>`;}
function refreshBank(){S.page=1;history.replaceState(null,'',url('bank',bankParams()));$('#results-meta').innerHTML=resultMeta();$('#results').innerHTML=resultRows();$('#pagination').innerHTML=pagination();if(S.selected)hydrateRecord(S.selected,S.token,false);announce(`${filtered().length} records match.`);}
async function fullRecord(id){const r=S.recordMap.get(id);if(!r)throw new Error('This record ID is not in the catalog.');if(r.type==='curated_comparison')return r;const sourceId=r.source_id,entry=arr(B().sources).find(s=>s.source_id===sourceId),d=entry?.shard;if(!d?.file)throw new Error('No bound source shard is supplied for this record.');if(!S.shards.has(sourceId)){if(!S.pending.has(sourceId))S.pending.set(sourceId,fetchJSON(d.file,d).then(x=>{if(x.source_id!==sourceId)throw new Error('Source shard identity mismatch.');const p=profile(sourceId);if(x.body_sha256&&p?.body_sha256&&x.body_sha256!==p.body_sha256)throw new Error('Source shard text-edition mismatch.');S.shards.set(sourceId,x);return x;}).finally(()=>S.pending.delete(sourceId)));await S.pending.get(sourceId);}const found=arr(S.shards.get(sourceId).records).find(x=>x.record_id===id);if(!found)throw new Error('The source shard does not contain the indexed record.');return {...r,...found};}
async function hydrateRecord(id,token,scroll=true){try{const r=await fullRecord(id);if(token!==S.token||id!==S.selected)return;$('#reader').innerHTML=recordDetail(r);if(scroll&&matchMedia('(max-width:1200px)').matches)$('#reader').scrollIntoView({block:'start'});}catch(e){if(token===S.token)$('#reader').innerHTML=error(e.message);}}
function recordDetail(r){const ps=sourceIds(r).map(profile).filter(Boolean),isCurated=r.type==='curated_comparison';return `${!filtered().some(x=>x.record_id===r.record_id)?'<div class="scope">This selected record is outside the active filters. Its evidence remains open for reference.</div>':''}${badge(r.type)}<h2>${esc(r.display_question)}</h2><p class="caption">${isCurated?'Source-informed analyst question; its construction and support are recorded below.':'Public indexing label, not a quotation of the recorded question. Question and answer locators identify the retained text edition.'}</p>${facts([['Question origin',esc(human(r.question_origin))],['Answer status',status(r.answer_status)],['Retained question wording',r.question_text_available===false?'Unavailable / editorial placeholder':r.question_text_available===true?'Retained privately; public label shown here':'See explicitly labeled question origin'],['Conditions / time interpretation',isCurated?'See each qualified answer below':esc(txt([r.conditions_status,r.time_scope_status].filter(Boolean)))],['Reading status',status(r.reading_status)],['Speaker status',esc(human(r.speaker_status||'source attribution only; unverified'))]])}${isCurated?r.cards.map(card=>`<section class="answer" id="${esc(card.card_id)}"><h3>${sourceLink(card.source_id)}</h3><p>${esc(card.paraphrase)}</p><div class="conditions"><strong>Conditions:</strong> ${esc(card.conditions)}<br><strong>Time scope:</strong> ${esc(card.time_scope)}<br><strong>Qualification:</strong> ${esc(card.qualifying_note)}</div><p class="caption">${esc(human(card.annotation?.type))} · Human validation: ${card.annotation?.human_validated===true?'recorded':'not claimed'}</p>${evidenceDetails(card.supports)}</section>`).join(''):r.answer_paraphrase?`<div class="answer"><h3>Supplied answer paraphrase</h3><p>${esc(r.answer_paraphrase)}</p></div>`:empty('No reviewed answer paraphrase is supplied for this record. A nearby span or question mark does not establish an answer.')}<h3>Source editions</h3>${ps.map(p=>`<div class="panel"><p>${sourceLink(p.source_id)}<small>${contextLink(p.channel_id)} · ${esc(origin(p))}</small></p>${!sourceMatchesFilters(p)?'<p class="caption">Comparison source outside the active source filters; retained to preserve the full analyst comparison.</p>':''}${facts([['Selected edition',`<code>${esc(p.selected_edition_id)}</code>`],['Normalized body SHA-256',`<code>${esc(p.body_sha256)}</code>`]])}<div class="actions">${inspectButton('source',p.source_id)}${graphLink('source:'+p.source_id)}</div></div>`).join('')}${!isCurated?evidenceDetails([r.question_span,...arr(r.answer_spans)].filter(Boolean)):''}<div class="actions">${inspectButton('record',r.record_id,'Inspect complete record metadata')}${isCurated?graphLink('question:'+r.question_id,'Follow this analyst question'):''}</div>`;}
function evidenceDetails(evidence){const rows=arr(evidence);return rows.length?`<details><summary>${num(rows.length)} source-bound evidence locators</summary>${rows.map(e=>facts([['Evidence role / ID',esc(txt(e.role||e.evidence_id||'Extraction locator'))],['Character range',`${num(e.start_character??e.start)}–${num(e.end_character??e.end)} (end-exclusive)`],['Span SHA-256',`<code>${esc(e.span_sha256)}</code>`],['Body SHA-256',`<code>${esc(e.body_sha256||'See selected source edition')}</code>`],['Timing qualifier',finite(e.start_seconds)?`${num(e.start_seconds,3)}–${num(e.end_seconds,3)} seconds; verify supplied timing scope`:'No word-level audio alignment asserted']])).join('')}</details>`:empty('No inspected evidence locator is supplied for this item.');}
function recordsForSource(id){return S.recordsBySource.get(id)||[];}
function sourceTable(rows){return table('Source profiles',['Selected source edition','Publishing context','Publication / text origin','Words / catalog entries'],rows.map(p=>`<tr><th scope="row">${sourceLink(p.source_id)}<small>${esc(human(p.summary_kind||'automatic_source_profile'))}</small></th><td>${contextLink(p.channel_id)}</td><td>${esc(date(p)||'Date unknown')}<small>${esc(human(origin(p)))}</small></td><td>${num(sourceWords(p))} words<small>${num(recordsForSource(p.source_id).length)} linked catalog entries</small></td></tr>`).join(''));}
function sourcesView(){return heading('SOURCE & CONTEXT DIGESTS','What has been processed and read.','Automatic lexical outlines cover the retained source frame. Bounded analyst readings and their inspected spans are separately identified.')+section('Publishing contexts','One context is a collection grouping, not an authenticated speaker or claimed entity.',table('Publishing contexts',['Context','Source units','Profiled words','Bounded reading scope','Browse'],contexts().map(c=>{const ps=P().filter(p=>p.channel_id===c.id),note=arr(C().context_notes).find(n=>n.channel_id===c.id);return `<tr><th scope="row">${contextLink(c.id)}</th><td>${num(ps.length)}</td><td>${num(ps.reduce((s,p)=>s+(sourceWords(p)||0),0))}</td><td>${note?`${status(note.reading_status)}<small>${num(arr(note.source_ids).length)} source units with declared supports</small>`:'No bounded reading supplied'}</td><td><a data-bank-context="${esc(c.id)}" href="${esc(url('bank',{channel:c.id}))}">Open matching records</a></td></tr>`;}).join('')))+section('Canonical source profiles','Titles link to exact source editions, automatic outlines, record lists and their provenance.',sourceTable(P()));}
function sourceView(id){const p=profile(id);if(!p)return heading('UNKNOWN SOURCE','This source is outside the release.','No substitute source edition is selected.');const linked=recordsForSource(id),read=arr(C().reading_coverage).find(r=>r.source_id===id),cards=arr(C().cards).filter(c=>c.source_id===id);return `<nav class="breadcrumb"><a data-view="sources" href="?view=sources">Source digests</a><span>/</span>${contextLink(p.channel_id)}<span>/</span><span>Selected edition</span></nav>`+heading('SELECTED SOURCE EDITION',sourceTitle(id),'Automatic processing and bounded source reading remain separate, even when they use the same retained text.')+`<div class="actions">${external(p.source_url)}${inspectButton('source',id)}${graphLink('source:'+id)}<a href="../channel-lab/?recording=${encodeURIComponent(id)}">Open numerical source profile</a></div><div class="split"><section class="panel"><h2>Automatic lexical outline</h2><p>${esc(p.summary||'No automatic outline supplied.')}</p><p class="caption">${esc(human(p.summary_kind))} · this is not an abstractive or verified whole-recording reading.</p><div class="terms">${topTerms(p).map(t=>`<span>${esc(t)}</span>`).join('')}</div>${facts([['Processed words',num(p.coverage?.processed_words)],['Retained words',num(p.coverage?.total_words??sourceWords(p))],['Human read',p.coverage?.human_read===true?'Recorded':'Not claimed'],['Audio listened',p.coverage?.audio_listened===true?'Recorded':'Not claimed']])}</section><section class="panel"><h2>Edition and coverage</h2>${facts([['Publisher context',contextLink(p.channel_id)],['Named creator context',esc(p.creator_name)],['Actual publisher',esc(p.publisher_name)],['Publication date',esc(date(p)||'Unknown')],['Text origin',esc(human(origin(p)))],['Selected edition',`<code>${esc(p.selected_edition_id)}</code>`],['Body SHA-256',`<code>${esc(p.body_sha256)}</code>`],['Newly inspected words',read?num(read.new_unique_words_read):'No bounded reading supplied'],['Prior inspected words',read?num(read.prior_unique_words_read):'No prior reading supplied']])}</section></div>`+section('Linked catalog entries',`${linked.length} unique catalog items refer to this source. Multi-source curated items may also appear under other sources. Zero observed documentary pairs is an extraction limit, not evidence of no spoken questions.`,recordTable(linked))+section('Bounded analyst paraphrases','These statements retain conditions and exact support locators; they do not replace the full source.',cards.length?cards.map(c=>`<article class="reader"><h3>${esc(C().questions.find(q=>q.question_id===c.question_id)?.question||c.question_id)}</h3><p>${esc(c.paraphrase)}</p><div class="conditions">${esc(c.conditions)}<br>${esc(c.qualifying_note)}</div>${evidenceDetails(c.supports)}<p>${recordLink('curated:'+c.question_id,'Open the full analyst comparison')}</p></article>`).join(''):empty('No bounded analyst answer was admitted for this source.'))}
function contextView(id){const ps=P().filter(p=>p.channel_id===id);if(!ps.length)return heading('UNKNOWN CONTEXT','This context is outside the source frame.','Screened accounts without retained text belong to the earlier collection audit.');const note=arr(C().context_notes).find(n=>n.channel_id===id),ids=new Set(ps.map(p=>p.source_id)),linked=S.records.filter(r=>sourceIds(r).some(s=>ids.has(s)));return `<nav class="breadcrumb"><a data-view="sources" href="?view=sources">Source digests</a><span>/</span><span>Publishing context</span></nav>`+heading('PUBLISHING CONTEXT',channelName(id),`${num(ps.length)} retained source editions · ${num(linked.length)} linked catalog items. This describes the retained sample, not lifetime uploads.`)+`<div class="actions"><a data-bank-context="${esc(id)}" href="${esc(url('bank',{channel:id}))}">Search this context’s records</a>${graphLink('channel:'+id,'Follow context connections')}<a href="../channel-lab/?channel=${encodeURIComponent(id)}">Open Channel Lab context</a></div>`+section('Source-bound context note','A bounded model-agent synthesis, with its reading denominator retained.',note?`<article class="reader">${status(note.reading_status)}<p>${esc(note.summary)}</p><div class="conditions">${esc(note.conditions)}</div>${facts([['Frame source units',num(note.frame_source_units)],['Supported source units',num(arr(note.source_ids).length)],['Newly inspected words',num(note.new_unique_words_read)],['Prior inspected words',num(note.prior_unique_words_read)],['Unreviewed source units',num(note.unreviewed_source_units)],['Coverage scope',esc(note.coverage_scope)]])}<p>${arr(note.source_ids).map(s=>sourceLink(s)).join(' · ')}</p></article>`:empty('No bounded context note supplied.'))+section('Included source editions','Open an edition to separate its automatic outline from inspected answer material.',sourceTable(ps))+section('Catalog composition','Types remain distinct; one curated comparison can link more than one context.',facts(Object.entries(TYPES).map(([k,v])=>[v.label,num(linked.filter(r=>r.type===k).length)])));}
function recordTable(rows){return table('Linked knowledge records',['Public question / index label','Record type','Answer / reading status','Inspect'],rows.map(r=>`<tr><th scope="row">${recordLink(r.record_id,r.display_question)}</th><td>${badge(r.type)}</td><td>${esc(human(r.answer_status))}<small>${esc(human(r.reading_status))}</small></td><td>${recordLink(r.record_id,'Read record')}</td></tr>`).join(''));}
function relationKeys(){const r=G().relation_types;return Array.isArray(r)?r.map(x=>typeof x==='string'?x:x.id||x.relation):Object.keys(r||{});}
function relationDefinition(key){const r=G().relation_types;return Array.isArray(r)?r.find(x=>x.id===key||x.relation===key):r?.[key];}
function graphSources(){let ps=P().filter(p=>(!S.graphChannels.length||S.graphChannels.includes(p.channel_id))&&(S.filter.origin==='all'||origin(p)===S.filter.origin)&&(S.filter.topic==='all'||dominant(p)===S.filter.topic)&&(!S.filter.from||date(p)&&date(p).slice(0,10)>=S.filter.from)&&(!S.filter.to||date(p)&&date(p).slice(0,10)<=S.filter.to));if(S.graphLabel&&S.graphLabel!=='all'){const ids=new Set(arr(G().edges).filter(e=>e.relation==='observed_label'&&(e.source===S.graphLabel||e.target===S.graphLabel)).map(e=>nodeMap().get(e.source===S.graphLabel?e.target:e.source)?.source_id));ps=ps.filter(p=>ids.has(p.source_id));}return ps;}
function graphFilterExtras(){const labels=arr(G().nodes).filter(n=>n.type==='observed_claimed_label'),topics=uniq(P().flatMap(p=>arr(p.topic_profile).map(t=>t.topic_id)));return `<div class="controls"><label>Exact printed attribution<select id="graph-label"><option value="all">All printed labels</option>${options(labels.map(n=>n.id),S.graphLabel,id=>nodeMap().get(id)?.label||id)}</select></label><label>Source text origin<select id="graph-origin">${allOptions(P().map(origin),S.filter.origin,'All origins')}</select></label><label>Source’s largest lexical factor<select id="graph-topic">${allOptions(topics,S.filter.topic,'All source factors')}</select></label><label>Published from<input id="graph-from" type="date" value="${esc(S.filter.from)}"></label><label>Published through<input id="graph-to" type="date" value="${esc(S.filter.to)}"></label></div><p class="caption">An exact printed attribution is a source label, not proof of shared entity identity. Factors are frozen lexical components. Date filters exclude unknown dates.</p>`;}
const NODE_TYPES=['publisher_context','creator_context','source','lexical_factor','observed_claimed_label','question','answer_card'];
const nodeMap=()=>S.graphNodes||new Map();
function nodeLink(id,label){const n=nodeMap().get(id);return `<a data-graph-node="${esc(id)}" href="${esc(url('graph',{node:id,channels:S.graphChannels,relations:S.relations,hops:S.hops}))}">${esc(label||n?.label||id)}</a>`;}
function filteredGraph(){const all=arr(G().nodes),sources=new Set(graphSources().map(p=>p.source_id)),creators=new Set(P().filter(p=>sources.has(p.source_id)).map(p=>p.creator_id)),nodes=all.filter(n=>{if(!sources.size)return false;if(n.source_id)return sources.has(n.source_id);if(arr(n.source_ids).length)return n.source_ids.some(s=>sources.has(s));if(n.channel_id)return P().some(p=>p.channel_id===n.channel_id&&sources.has(p.source_id));if(n.type==='creator_context')return creators.has(n.creator_id);return true;}),ids=new Set(nodes.map(n=>n.id)),edges=arr(G().edges).filter(e=>ids.has(e.source)&&ids.has(e.target)&&S.relations.includes(e.relation));return {nodes,edges};}
function neighborhood(graph,seed,hops){if(!seed)return graph;const valid=new Set(graph.nodes.map(n=>n.id));if(!valid.has(seed))return {nodes:[],edges:[],paths:[]};const found=new Set([seed]),paths=[],queue=[{id:seed,edges:[],ids:[seed]}];for(let i=0;i<queue.length;i++){const row=queue[i];if(row.edges.length>=hops)continue;for(const e of graph.edges){const next=e.source===row.id?e.target:e.target===row.id?e.source:null;if(!next||row.ids.includes(next))continue;const p={id:next,edges:[...row.edges,e],ids:[...row.ids,next]};paths.push(p);if(!found.has(next)){found.add(next);queue.push(p);}}}return {nodes:graph.nodes.filter(n=>found.has(n.id)),edges:graph.edges.filter(e=>found.has(e.source)&&found.has(e.target)),paths};}
function graphView(){if(!S.modules.graph)return unavailable('graph');if(!S.node&&!new URLSearchParams(location.search).has('all'))S.node='source:'+P()[0]?.source_id;const filtered=filteredGraph(),selected=neighborhood(filtered,S.node,S.hops);S.currentGraph=selected;S.filteredGraph=filtered;return heading('TYPED CONNECTION EXPLORER','Follow the relationship, then the source.','Browse publishing, attribution, lexical-factor and evidence-support paths. A connection is only the relation printed on its edge.')+`<details class="panel"><summary>Context and relation filters</summary><h3>Publishing contexts</h3><p class="caption">No selected context means all retained contexts. Shared factor and label nodes retain their own types.</p><div class="choice-list">${contexts().map(c=>`<label><input type="checkbox" name="graph-channel" value="${esc(c.id)}" ${S.graphChannels.includes(c.id)?'checked':''}>${esc(c.name)}</label>`).join('')}</div><h3>Relations</h3><div class="choice-list">${relationKeys().map(k=>`<label><input type="checkbox" name="graph-relation" value="${esc(k)}" ${S.relations.includes(k)?'checked':''}>${esc(human(k))}</label>`).join('')}</div>${graphFilterExtras()}<button type="button" id="apply-graph-filters">Apply graph filters</button></details><div class="controls"><label>Focus node<select id="graph-node"><option value="">Combined filtered graph</option>${filtered.nodes.map(n=>`<option value="${esc(n.id)}" ${n.id===S.node?'selected':''}>${esc(human(n.type))}: ${esc(n.label)}</option>`).join('')}</select></label><label>Path distance<select id="graph-hops">${options([1,2],S.hops,x=>x===1?'One relation':'Up to two relations')}</select></label><button type="button" id="apply-graph-focus">Show connections</button><button type="button" class="secondary" id="export-graph">Export edges CSV</button><button type="button" class="secondary" id="export-graph-json">Export graph JSON</button></div><div class="result-meta"><strong>${num(selected.nodes.length)} nodes · ${num(selected.edges.length)} edges in this view</strong><span>${num(filtered.nodes.length)} eligible nodes · ${num(filtered.edges.length)} edges after filters</span></div><p class="caption">Included annotation types: ${esc(txt(G().coverage?.included_annotation_types||G().coverage?.eligible_record_types))}. Omitted record counts: ${esc(txt(G().coverage?.omitted_record_counts))}. ${esc(G().coverage?.omission_scope||'')} No omitted candidate is silently interpreted as evidence.</p>${graphPlot(selected)}${S.node?section('Actual typed paths','Traversal is undirected for discovery; arrows below retain the original edge direction. Only simple paths within the selected hop bound are listed.',pathList(selected.paths||[])):''}`+section('Exact edge records','The table and export use the same filtered neighborhood. Diagram caps do not delete export rows.',edgeTable(selected.edges))+section('Selected node and relation provenance','Evidence support resolves to exact source editions and inspected span hashes.',nodeDetails(S.node))+section('Graph definitions','Cosine and NMF weights have different units. Unweighted metadata/support relations are not probabilities.',facts(relationKeys().map(k=>[human(k),esc(txt(relationDefinition(k)))])));}
function graphPlot(graph){if(!graph.nodes.length)return empty('No graph node matches the current focus and filters. Choose a node within the selected contexts.');const types=uniq(graph.nodes.map(n=>n.type)).sort(),rank=n=>types.indexOf(n.type),all=[...graph.nodes].sort((a,b)=>rank(a)-rank(b)||a.label.localeCompare(b.label)||a.id.localeCompare(b.id)),shown=all.slice(0,180),ids=new Set(shown.map(n=>n.id)),edges=graph.edges.filter(e=>ids.has(e.source)&&ids.has(e.target)).slice(0,700),positions=new Map(),height=Math.max(500,Math.min(1600,Math.max(...types.map(t=>shown.filter(n=>n.type===t).length))*25+75)),width=Math.max(1000,types.length*155);types.forEach((t,j)=>{const rows=shown.filter(n=>n.type===t);rows.forEach((n,i)=>positions.set(n.id,{x:50+j*(width-100)/Math.max(1,types.length-1),y:65+(i+.5)*(height-100)/Math.max(1,rows.length)}));});const colors=['#285b49','#28677f','#84572f','#75618b','#8a493d','#5f743d','#986e1f'];return `<p class="caption">Typed-column layout; position and line length carry no semantic distance. Drawing ${num(shown.length)} of ${num(graph.nodes.length)} nodes and ${num(edges.length)} of ${num(graph.edges.length)} edges, in stable type/label order. Full records remain in the table/export.</p><div class="plot-scroll" tabindex="0" role="region" aria-label="Typed source-knowledge graph"><svg class="graph" viewBox="0 0 ${width} ${height}">${types.map((t,i)=>`<line class="lane" x1="${50+i*(width-100)/Math.max(1,types.length-1)}" x2="${50+i*(width-100)/Math.max(1,types.length-1)}" y1="45" y2="${height-20}"/><text x="${50+i*(width-100)/Math.max(1,types.length-1)}" y="25" text-anchor="middle">${esc(human(t))}</text>`).join('')}${edges.map(e=>{const a=positions.get(e.source),b=positions.get(e.target);return `<line class="edge ${e.relation==='derived_semantic_neighbor'?'derived':''}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"><title>${esc(human(e.relation))}${finite(e.weight)?' · '+num(e.weight,4):''}</title></line>`;}).join('')}${shown.map(n=>{const p=positions.get(n.id),color=colors[NODE_TYPES.indexOf(n.type)%colors.length];return `<a data-graph-node="${esc(n.id)}" href="${esc(url('graph',{node:n.id,channels:S.graphChannels,relations:S.relations,hops:S.hops}))}"><circle data-node="${esc(n.id)}" cx="${p.x}" cy="${p.y}" r="${n.id===S.node?8:5}" fill="${color}" stroke="#fffef9" stroke-width="1.2"><title>${esc(human(n.type))}: ${esc(n.label)}</title></circle>${shown.length<=35?`<text x="${p.x+(types.indexOf(n.type)===types.length-1?-10:10)}" y="${p.y+4}" text-anchor="${types.indexOf(n.type)===types.length-1?'end':'start'}">${esc(n.label.length>24?n.label.slice(0,23)+'…':n.label)}</text>`:''}</a>`;}).join('')}</svg></div><div class="legend">${types.map((t,i)=>`<span><i class="swatch" style="--swatch:${colors[NODE_TYPES.indexOf(t)%colors.length]}"></i>${esc(human(t))}</span>`).join('')}</div>`;}
function pathList(paths){const unique=new Map();for(const p of paths){const key=p.ids.join('|');if(!unique.has(key))unique.set(key,p);}const rows=[...unique.values()];return rows.length?`<p class="caption">${num(rows.length)} distinct simple node paths; first 60 shown. A shared name, context or factor does not establish agreement or entity identity.</p><ol class="path-list">${rows.slice(0,60).map(p=>`<li>${p.ids.map((id,i)=>`${i?`<span class="verb">${p.edges[i-1].source===p.ids[i-1]?'→':'←'} ${esc(human(p.edges[i-1].relation))} ${p.edges[i-1].source===p.ids[i-1]?'→':'←'}</span>`:''}${nodeLink(id)}`).join('')}</li>`).join('')}</ol>`:empty('No eligible relation path leaves the selected node.');}
function edgeTable(edges){const pages=Math.max(1,Math.ceil(edges.length/40));S.graphPage=Math.min(Math.max(1,S.graphPage),pages);return table('Typed graph edge records',['From node','Relation / weight','To node','Evidence'],edges.slice((S.graphPage-1)*40,S.graphPage*40).map(e=>`<tr><th scope="row">${nodeLink(e.source)}</th><td>${esc(human(e.relation))}<small>${finite(e.weight)?num(e.weight,5):'Unweighted relation'}</small></td><td>${nodeLink(e.target)}</td><td>${arr(e.evidence_ids).length?inspectButton('edge',e.id,`${e.evidence_ids.length} evidence locators`):esc(human(e.origin||'Metadata relation'))}</td></tr>`).join(''))+`<div class="pagination"><button type="button" class="secondary" data-edge-page="${S.graphPage-1}" ${S.graphPage===1?'disabled':''}>Previous edges</button><span>Page ${S.graphPage} of ${pages}</span><button type="button" class="secondary" data-edge-page="${S.graphPage+1}" ${S.graphPage===pages?'disabled':''}>Next edges</button></div>`;}
function nodeDetails(id){const n=nodeMap().get(id),card=n?.card_id?arr(C().cards).find(c=>c.card_id===n.card_id):null;if(!n)return empty('Select a node to inspect its declared type and source links.');return `<div class="panel"><h3>${esc(card?'Qualified source-reading card':n.label)}</h3>${card?`<p>${esc(card.paraphrase)}</p><div class="conditions"><strong>Conditions:</strong> ${esc(card.conditions)}<br><strong>Time scope:</strong> ${esc(card.time_scope)}<br><strong>Qualification:</strong> ${esc(card.qualifying_note)}</div>`:''}${facts([['Node type',esc(human(n.type))],['Status',esc(human(n.status||'See relation definition'))],['Node ID',`<code>${esc(n.id)}</code>`]])}<div class="actions">${n.source_id?sourceLink(n.source_id):''}${arr(n.source_ids).map(s=>sourceLink(s)).join(' · ')}${n.channel_id?contextLink(n.channel_id):''}${n.question_id&&S.recordMap.has('curated:'+n.question_id)?recordLink('curated:'+n.question_id,'Open curated question'):''}${inspectButton('node',n.id)}</div></div>`;}
function moduleFile(k){return safeFile(S.manifest?.modules?.[k]?.file);}
function retrievalRankSummary(r){const keys=['bm25','tfidf','minilm','rrf'];return table('Known-support source ranks',['Frozen query / scope','Passage BM25','Document TF-IDF','Document MiniLM','Rank fusion'],arr(r.queries).map(q=>`<tr><th scope="row">${esc(q.query_id||q.id)} · ${esc(human(q.question_family||q.query_type))}<small>${esc(q.query||q.text)}</small></th>${keys.map(k=>`<td class="numeric">${q.conditions?.[k]?.metrics?num(q.conditions[k].metrics.first_known_support_rank):'Unscored'}</td>`).join('')}</tr>`).join(''))+`<p class="caption">First known-support source rank; smaller is earlier, not more truthful. A method can rank a known support poorly even when its aggregate summary is strong. Controls have no fabricated positive set.</p>${arr(r.figures).filter(f=>/\.png$/i.test(f.file||'')).map(f=>{const file=f.file.includes('/')?f.file:'figures/'+f.file;return `<figure class="research-figure"><a href="${esc(file)}"><img loading="lazy" src="${esc(file)}" alt="Frozen retrieval diagnostic, including method disagreement and known-support source ranks"></a><figcaption>Source-informed, partially judged retrieval comparison. No claim of held-out human accuracy.</figcaption></figure>`;}).join('')}`;}
function retrievalView(){const r=S.modules.retrieval;if(!r)return unavailable('retrieval');return `${retrievalRankSummary(r)}<p class="caption">${esc(txt(r.settings?.scope||r.scope||'Frozen source-informed retrieval diagnostics; known supports are partial judgments, not held-out human answer accuracy.'))}</p><details class="panel"><summary>Coverage and measured summaries</summary>${facts(Object.entries(r.coverage||{}).map(([k,v])=>[human(k),esc(txt(v))]))}<pre>${esc(JSON.stringify(r.summaries||{},null,2))}</pre></details>${arr(r.queries).map(q=>{const conditions=Array.isArray(q.conditions)?q.conditions.map(c=>[c.id||c.condition||c.name,c]):Object.entries(q.conditions||{});return `<article class="reader"><span class="eyebrow">${esc(q.id||q.query_id)} · ${esc(human(q.type||q.query_type))}</span><h3>${esc(q.text||q.query||q.question)}</h3><p class="caption">Information-need category: ${esc(human(q.question_family||q.family||'See supplied bindings'))}. Source contexts: ${esc(txt(q.source_family_ids))}. Known-support source ranks do not establish answer completeness; unjudged sources are not negatives.</p>${conditions.map(([name,c])=>`<details><summary>${esc(human(name))} · inspect retained top results</summary>${c.metrics===null?'<p class="caption">Unscored control: returned candidates do not establish answerability or verified identity.</p>':''}${facts(Object.entries(c.metrics||{}).map(([k,v])=>[human(k),esc(txt(v))]))}<p class="caption">Known-support ranks: ${esc(txt(c.metrics?.known_support_ranks??c.known_support_ranks??c.support_ranks??'Unscored control / no judged positive set'))}</p>${table('Frozen retrieval results',['Rank','Source edition','Supplied score / evidence'],arr(c.top_results).map((x,i)=>`<tr><td>${num(x.rank??i+1)}</td><th scope="row">${sourceLink(x.source_id)}</th><td>${finite(x.score)?num(x.score,6):esc(txt(x.scores||'See retained condition metadata'))}<small>${esc(x.citation?.locator_kind||txt(x.evidence_ids||x.passage_id))}</small>${inspectButton('retrieval',(q.query_id||q.id)+'|'+name+'|'+(x.rank??i+1),'Inspect ranking citation')}</td></tr>`).join(''))}</details>`).join('')}</article>`;}).join('')}<ul>${arr(r.limitations).map(x=>`<li>${esc(txt(x))}</li>`).join('')}</ul>`;}
function literatureView(){const l=S.modules.literature;if(!l)return unavailable('literature');const rows=arr(l.records||l.sources);return rows.map(r=>`<article class="panel"><h3>${esc(r.title||r.id)}</h3>${status(r.implementation_status)}<p>${esc(txt(r.inspected_scope||r.application||r.local_component))}</p><div class="actions">${external(r.primary_url||r.url||r.artifacts?.[0]?.url,'Primary reference')}${r.repository?.url?external(r.repository.url,'Repository'):''}</div><p class="caption">${esc(txt(r.limitations||r.limitation))}</p><details><summary>Access depth and artifact bindings</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details></article>`).join('')||empty('No public literature records supplied.');}
function methodsView(){return heading('METHODS & DOWNLOADS','Separate extraction, reading and retrieval.','Inspect the automated record types, bounded analyst coverage, typed graph definitions and frozen retrieval experiments behind this release.')+section('Catalog and reading denominators','A catalog item is not an independent historical session or a verified answer.',facts([['Canonical source profiles',num(P().length)],['Extraction / prompt entries',num(arr(B().records).length)],['Curated questions',num(arr(C().questions).length)],['Qualified answer cards',num(arr(C().cards).length)],['Publishing contexts',num(contexts().length)],...Object.entries(C().coverage||{}).map(([k,v])=>[human(k),esc(txt(v))])]))+section('Browser search','MiniSearch indexes bounded public annotations and source metadata. It does not search the private full transcript bodies.',`<div class="panel"><h3>MiniSearch 7.2.0 · BM25+</h3><p>OR token matching, no fuzzy or prefix matching by default. Unicode letters, combining marks, numerals and internal apostrophes are preserved; there is no stop-word list, so negation remains searchable. BM25+ defaults are k=1.2, b=0.7 and δ=0.5.</p><p class="caption">Question labels, curated answer paraphrases, source titles, publishing metadata and lexical terms are indexed. These scores are not SQLite FTS5 BM25 scores, semantic similarity, answer correctness or evidence strength.</p><div class="actions"><a href="vendor/minisearch.provenance.json">Pinned package provenance</a><a href="vendor/minisearch.LICENSE.txt">MIT license</a></div></div>`)+section('Frozen retrieval comparison','These are retained diagnostic runs, not new queries executed against private bodies in this browser.',retrievalView())+section('Graph and source limitations','Metadata links, lexical factors, support relations and model similarities remain different evidence types.',`<ul>${[...arr(B().limitations),...arr(S.modules.profiles?.limitations),...arr(C().limitations),...arr(G().limitations)].map(x=>`<li>${esc(txt(x))}</li>`).join('')}</ul>`)+section('Inspected software and research','Reference-only tools are not represented as implemented algorithms.',literatureView())+section('Download the public release','Public SQLite/GraphML and JSON contain sanitized metadata and annotations. Private passage search and source text bodies are not exported.',downloadLinks());}
function downloadLinks(){return `<div class="downloads">${Object.keys(S.modules).map(k=>`<a href="${esc(moduleFile(k))}" download>${esc(human(k))} JSON</a>`).join('')}${arr(S.manifest.artifacts).filter(a=>/\.(sqlite|graphml|csv|md|pdf|zip)$/i.test(a.file||'')).map(a=>`<a href="${esc(a.file)}" download>${esc(a.file)}</a>`).join('')}<a href="manifest.json" download>Release manifest</a></div><details><summary>Public database scope</summary>${S.modules.database?facts(Object.entries(S.modules.database.search_scope||{}).map(([k,v])=>[human(k),esc(txt(v))])):unavailable('database')}</details>`;}
async function openInspector(kind,id,trigger){S.trigger=trigger;const request=S.inspectRequest=(S.inspectRequest||0)+1;$('#inspector-body').innerHTML='<h2 id="inspector-title">Loading provenance</h2>';$('#inspector').showModal();try{let data,title,extra='';if(kind==='source'){data=profile(id);title=sourceTitle(id);}else if(kind==='record'){data=await fullRecord(id);title=data.display_question;}else if(kind==='retrieval'){const [qid,condition,rank]=id.split('|'),q=arr(S.modules.retrieval?.queries).find(q=>(q.query_id||q.id)===qid);data=q?.conditions?.[condition]?.top_results?.find(r=>r.rank===Number(rank));title=data?.citation?.title||'Retrieval citation';extra='<p class="caption">This is a ranking citation, not automatically judged answer evidence. Inspect its locator kind and source edition.</p>';}else if(kind==='edge'){data=arr(G().edges).find(e=>e.id===id);title=human(data?.relation);const evidence=arr(data?.evidence_ids).map(e=>G().evidence?.[e]).filter(Boolean);extra=evidenceDetails(evidence);if(evidence.length!==arr(data?.evidence_ids).length)extra+=empty('Some evidence IDs do not resolve in the public JSON map; inspect the database before interpreting this edge.');}else{data=nodeMap().get(id);title=data?.label;const card=data?.card_id?arr(C().cards).find(c=>c.card_id===data.card_id):null;if(card)data={...data,qualified_card:card};}if(!data)throw new Error('No bound metadata record matches this ID.');if(request!==S.inspectRequest||!$('#inspector').open)return;$('#inspector-body').innerHTML=`<h2 id="inspector-title">${esc(title)}</h2><p class="caption">Sanitized public metadata; a locator is not a copied transcript or a verified speaker identity.</p>${extra}<pre>${esc(JSON.stringify(data,null,2))}</pre>`;}catch(e){if(request===S.inspectRequest&&$('#inspector').open)$('#inspector-body').innerHTML='<h2 id="inspector-title">Provenance unavailable</h2>'+error(e.message);}}
function closeInspector(){S.inspectRequest=(S.inspectRequest||0)+1;$('#inspector').close();S.trigger?.isConnected&&S.trigger.focus();}
function download(name,body,mime){const link=document.createElement('a'),object=URL.createObjectURL(new Blob([body],{type:mime}));link.href=object;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(object),1000);}
function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
const csv=rows=>rows.map(r=>r.map(csvCell).join(',')).join('\r\n');
function exportedRecords(){const rows=filtered(),ids=uniq(rows.flatMap(sourceIds));return {schema_version:1,release_modules:S.manifest.modules,scope:'Filtered public index metadata, not original question/answer text or a full transcript export. A comparison qualifies when one linked source meets every source filter; all comparison sources are retained and flagged separately',filters:{...S.filter,query:S.query,prefix:S.prefix},records:rows.map(r=>({record_id:r.record_id,type:r.type,display_question:r.display_question,source_ids:sourceIds(r),question_origin:r.question_origin,answer_status:r.answer_status,reading_status:r.reading_status,topic_terms:r.topic_terms,deep_link:new URL(url('bank',{record:r.record_id}),location.href).href})),sources:ids.map(id=>{const p=profile(id);return {source_id:id,title:p?.title,source_url:p?.source_url,channel_id:p?.channel_id,selected_edition_id:p?.selected_edition_id,body_sha256:p?.body_sha256,matches_active_source_filters:sourceMatchesFilters(p)};})};}
function exportRecords(format){const data=exportedRecords();if(format==='json')download('filtered-knowledge-records.json',JSON.stringify(data,null,2),'application/json');else download('filtered-knowledge-records.csv',csv([['record_id','type','public_index_label','source_ids','matching_source_ids','source_urls','answer_status','reading_status','deep_link','filters','scope'],...data.records.map(r=>[r.record_id,r.type,r.display_question,r.source_ids.join('|'),r.source_ids.filter(id=>sourceMatchesFilters(profile(id))).join('|'),r.source_ids.map(id=>profile(id)?.source_url||'').join('|'),r.answer_status,r.reading_status,r.deep_link,JSON.stringify(data.filters),data.scope])]),'text/csv;charset=utf-8');announce(`${data.records.length} filtered catalog items exported.`);}
function exportGraph(){const data=S.currentGraph;if(!data)return;download('filtered-knowledge-edges.csv',csv([['edge_id','source_node','relation','target_node','weight','evidence_ids','context_filter','focus_node','hops','all_filters','scope'],...data.edges.map(e=>[e.id,e.source,e.relation,e.target,e.weight,arr(e.evidence_ids).join('|'),S.graphChannels.join('|'),S.node||'combined',S.hops,JSON.stringify(graphParams()),'Actual typed relation; proximity/path is not agreement or verified identity'])]),'text/csv;charset=utf-8');}
function applyFilters(){const candidate={...S.filter};for(const key of Object.keys(candidate))candidate[key]=$('#filter-'+key).value;const end=$('#filter-to');end.setCustomValidity('');if(candidate.from&&candidate.to&&candidate.from>candidate.to){end.setCustomValidity('The end date must be on or after the start date.');end.reportValidity();return;}S.filter=candidate;refreshBank();}
function graphParams(){return {node:S.node,channels:S.graphChannels,relations:S.relations,hops:S.hops,all:S.node?'':'1',label:S.graphLabel,origin:S.filter.origin,topic:S.filter.topic,from:S.filter.from,to:S.filter.to};}
function bind(){
 if($('#search-form'))$('#search-form').onsubmit=e=>{e.preventDefault();S.query=$('#query').value;S.prefix=$('#prefix').checked;refreshBank();};
 for(const key of Object.keys(S.filter))if($('#filter-'+key))$('#filter-'+key).onchange=applyFilters;
 if($('#clear-filters'))$('#clear-filters').onclick=()=>go('bank');
 if($('#export-records'))$('#export-records').onclick=()=>exportRecords('csv');
 if($('#export-records-json'))$('#export-records-json').onclick=()=>exportRecords('json');
 if($('#apply-graph-filters'))$('#apply-graph-filters').onclick=()=>{S.graphChannels=[...document.querySelectorAll('[name="graph-channel"]:checked')].map(x=>x.value);S.relations=[...document.querySelectorAll('[name="graph-relation"]:checked')].map(x=>x.value);S.graphLabel=$('#graph-label').value;S.filter.origin=$('#graph-origin').value;S.filter.topic=$('#graph-topic').value;S.filter.from=$('#graph-from').value;S.filter.to=$('#graph-to').value;if(S.filter.from&&S.filter.to&&S.filter.from>S.filter.to){$('#graph-to').setCustomValidity('End date must follow the start date.');$('#graph-to').reportValidity();return;}go('graph',graphParams());};
 if($('#apply-graph-focus'))$('#apply-graph-focus').onclick=()=>{S.node=$('#graph-node').value||null;S.hops=Number($('#graph-hops').value);go('graph',graphParams());};
 if($('#export-graph'))$('#export-graph').onclick=exportGraph;if($('#export-graph-json'))$('#export-graph-json').onclick=()=>download('filtered-knowledge-graph.json',JSON.stringify({scope:'Typed source relations; not authenticated entities or agreement',filters:graphParams(),release_modules:S.manifest.modules,nodes:S.currentGraph.nodes,edges:S.currentGraph.edges},null,2),'application/json');
}
document.addEventListener('click',e=>{const a=e.target.closest('[data-view],[data-record],[data-source],[data-context],[data-bank-context],[data-graph-node],[data-inspect],[data-type],[data-page],[data-edge-page]');if(!a||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;if(a.dataset.inspect){openInspector(a.dataset.inspect,a.dataset.id,a);return;}if(a.dataset.page){S.page=Number(a.dataset.page);$('#results').innerHTML=resultRows();$('#pagination').innerHTML=pagination();return;}if(a.dataset.edgePage){S.graphPage=Number(a.dataset.edgePage);render();return;}e.preventDefault();if(a.dataset.record)go('bank',{...bankParams(),record:a.dataset.record});else if(a.dataset.source)go('source',{source:a.dataset.source});else if(a.dataset.context)go('context',{context:a.dataset.context});else if(a.dataset.bankContext)go('bank',{channel:a.dataset.bankContext});else if(a.dataset.graphNode)go('graph',{...graphParams(),node:a.dataset.graphNode,all:null});else if(a.dataset.type)go('bank',{...bankParams(),type:a.dataset.type,record:null});else go(a.dataset.view);});
$('#close-inspector').onclick=closeInspector;$('#inspector').addEventListener('close',()=>{S.inspectRequest=(S.inspectRequest||0)+1;S.trigger?.isConnected&&S.trigger.focus();});window.addEventListener('popstate',()=>{readRoute();render();});
load();
